    seoTitle: {"en":"Twitch Statistics 2025: 19.2 Billion Hours, Viewers, Market Share & Full Data","no":"Twitch-statistikk 2025: 19,2 milliarder timer, seertall, markedsandel og fulldata","sv":"Twitch-statistik 2025: 19,2 miljarder timmar, tittare, marknadsandel & fulldata","fi":"Twitch-tilastot 2025: 19,2 miljardia tuntia, katsojat, markkinaosuus & täysi data"},
    seoDescription: {"en":"Twitch 2025: 19.2B hours (-8.9%), 52.8% market share, 2.3M concurrent viewers. Quarterly breakdown, non-gaming growth to 22%, and platform comparisons.","no":"Twitch 2025: 19,2 milliarder timer sett (-8,9%), 52,8% markedsandel, 91 400 kanaler live samtidig, 2,3M samtidige seere. Full kvartalsoversikt og plattformsammenligninger.","sv":"Twitch 2025: 19,2 miljarder timmar tittade (-8,9%), 52,8% marknadsandel, 91 400 kanaler live samtidigt, 2,3M samtida tittare. Fullständig kvartalsöversikt och plattformsjämförelser.","fi":"Twitch 2025: 19,2 miljardia katsottua tuntia (-8,9%), 52,8% markkinaosuus, 91 400 kanavaa live yhtä aikaa, 2,3M samanaikaista katsojaa. Täysi neljännesvuositarkastelu ja alustavertailut."},
    seoKeywords: {"en":["twitch statistics 2025","twitch hours watched","twitch market share","streamhatchet report","twitch viewbotting"],"no":["twitch statistikk 2025","twitch timer sett","twitch markedsandel"],"sv":["twitch statistik 2025","twitch timmar tittade","twitch marknadsandel"],"fi":["twitch tilastot 2025","twitch tunnit katsottu","twitch markkinaosuus"]},
